func TotalTokens(sessionsRoot, parentThreadID, taskIdentity string, previousTotal *int64) (int64, bool) {
	if strings.TrimSpace(parentThreadID) == "" || strings.TrimSpace(taskIdentity) == "" || previousTotal != nil && *previousTotal < 0 {
		return 0, false
	}
	var totals []int64
	err := filepath.WalkDir(sessionsRoot, func(path string, entry fs.DirEntry, walkErr error) error {
		if walkErr != nil { return walkErr }
		if entry.IsDir() || filepath.Ext(entry.Name()) != ".jsonl" { return nil }
		total, candidate, valid := rolloutTotal(path, parentThreadID, taskIdentity)
		if !candidate { return nil }
		if !valid { return errInvalidRollout }
		totals = append(totals, total)
		return nil
	})
	if err != nil || len(totals) != 1 { return 0, false }
	total := totals[0]
	if previousTotal == nil { return total, true }
	if *previousTotal > total { return 0, false }
	return total - *previousTotal, true
}
